pub unsafe fn BrotliStoreUncompressedMetaBlock(
    mut is_final_block: c_int,
    mut input: *const uint8_t,
    mut position: size_t,
    mut mask: size_t,
    mut len: size_t,
    mut storage_ix: *mut size_t,
    mut storage: *mut uint8_t,
) {
    let mut masked_pos: size_t = position & mask;
    BrotliStoreUncompressedMetaBlockHeader(len, storage_ix, storage);
    JumpToByteBoundary(storage_ix, storage);

    let mut ix = *storage_ix;
    let mut dst = storage.offset((ix >> 3) as isize);

    if masked_pos.wrapping_add(len) > mask.wrapping_add(1 as size_t) {
        let len1 = mask.wrapping_add(1 as size_t).wrapping_sub(masked_pos);
        memcpy(
            dst as *mut c_void,
            input.offset(masked_pos as isize) as *const c_void,
            len1,
        );
        ix = (ix as c_ulong).wrapping_add((len1 << 3) as c_ulong) as size_t;
        len = (len as c_ulong).wrapping_sub(len1 as c_ulong) as size_t;
        masked_pos = 0;
        dst = storage.offset((ix >> 3) as isize);
    }

    memcpy(
        dst as *mut c_void,
        input.offset(masked_pos as isize) as *const c_void,
        len,
    );
    ix = (ix as c_ulong).wrapping_add((len << 3) as c_ulong) as size_t;
    *storage_ix = ix;

    BrotliWriteBitsPrepareStorage(ix, storage);
    if is_final_block != 0 {
        BrotliWriteBits(1 as size_t, 1 as uint64_t, storage_ix, storage);
        BrotliWriteBits(1 as size_t, 1 as uint64_t, storage_ix, storage);
        JumpToByteBoundary(storage_ix, storage);
    }
