#[inline]
pub unsafe fn BrotliPopulationCostLiteral(
    mut histogram: *const HistogramLiteral,
) -> c_double {
    static mut kOneSymbolHistogramCost: c_double = 12 as c_int as c_double;
    static mut kTwoSymbolHistogramCost: c_double = 20 as c_int as c_double;
    static mut kThreeSymbolHistogramCost: c_double = 28 as c_int as c_double;
    static mut kFourSymbolHistogramCost: c_double = 37 as c_int as c_double;

    let data_size: size_t = HistogramDataSizeLiteral() as size_t;
    // SAFETY: caller guarantees `histogram` is a valid pointer to `HistogramLiteral`.
    let h = unsafe { &*histogram };

    if h.total_count_ == 0 as size_t {
        return kOneSymbolHistogramCost;
    }

    let data = &h.data_;
    let mut s: [size_t; 5] = [0; 5];
    let mut count: c_int = 0;
    let mut i: size_t = 0;

    while i < data_size {
        if data[i as usize] != 0 {
            s[count as usize] = i;
            count += 1;
            if count > 4 {
                break;
            }
        }
        i = i.wrapping_add(1);
    }

    if count == 1 {
        return kOneSymbolHistogramCost;
    }
    if count == 2 {
        return kTwoSymbolHistogramCost + h.total_count_ as c_double;
    }
    if count == 3 {
        let histo0 = data[s[0] as usize];
        let histo1 = data[s[1] as usize];
        let histo2 = data[s[2] as usize];
        let histomax = brotli_max_uint32_t(histo0, brotli_max_uint32_t(histo1, histo2)) as uint32_t;
        return kThreeSymbolHistogramCost
            + (2 as uint32_t).wrapping_mul(histo0.wrapping_add(histo1).wrapping_add(histo2))
                as c_double
            - histomax as c_double;
    }
    if count == 4 {
        let mut a = data[s[0] as usize];
        let mut b = data[s[1] as usize];
        let mut c = data[s[2] as usize];
        let mut d = data[s[3] as usize];

        if b > a {
            core::mem::swap(&mut a, &mut b);
        }
        if c > a {
            core::mem::swap(&mut a, &mut c);
        }
        if d > a {
            core::mem::swap(&mut a, &mut d);
        }
        if c > b {
            core::mem::swap(&mut b, &mut c);
        }
        if d > b {
            core::mem::swap(&mut b, &mut d);
        }
        if d > c {
            core::mem::swap(&mut c, &mut d);
        }

        let h23 = c.wrapping_add(d);
        let histomax_0 = brotli_max_uint32_t(h23, a);
        return kFourSymbolHistogramCost
            + (3 as uint32_t).wrapping_mul(h23) as c_double
            + (2 as uint32_t).wrapping_mul(a.wrapping_add(b)) as c_double
            - histomax_0 as c_double;
    }

    let mut max_depth: size_t = 1;
    let mut depth_histo: [uint32_t; 18] = [0; 18];
    let log2total: c_double = FastLog2(h.total_count_) as c_double;
    let mut bits: c_double = 0.0f64;
    i = 0;

    while i < data_size {
        let v = data[i as usize];
        if v != 0 {
            let log2p: c_double = log2total - FastLog2(v as size_t);
            let mut depth: size_t = (log2p + 0.5f64) as size_t;
            bits += v as c_double * log2p;
            if depth > 15 {
                depth = 15;
            }
            if depth > max_depth {
                max_depth = depth;
            }
            depth_histo[depth as usize] = depth_histo[depth as usize].wrapping_add(1);
            i = i.wrapping_add(1);
        } else {
            let mut reps: uint32_t = 1;
            let mut k = i.wrapping_add(1);
            while k < data_size && data[k as usize] == 0 {
                reps = reps.wrapping_add(1);
                k = k.wrapping_add(1);
            }
            i = (i as c_ulong).wrapping_add(reps as c_ulong) as size_t;
            if i == data_size {
                break;
            }
            if reps < 3 {
                depth_histo[0] = (depth_histo[0] as c_uint).wrapping_add(reps as c_uint) as uint32_t;
            } else {
                reps = (reps as c_uint).wrapping_sub(2 as c_uint) as uint32_t;
                while reps > 0 {
                    depth_histo[BROTLI_REPEAT_ZERO_CODE_LENGTH as usize] =
                        depth_histo[BROTLI_REPEAT_ZERO_CODE_LENGTH as usize].wrapping_add(1);
                    bits += 3 as c_int as c_double;
                    reps >>= 3;
                }
            }
        }
    }

    bits += (18 as size_t).wrapping_add((2 as size_t).wrapping_mul(max_depth)) as c_double;
    bits += BrotliBitsEntropy(
        &raw mut depth_histo as *mut uint32_t,
        BROTLI_CODE_LENGTH_CODES as size_t,
    );
    bits
}
