#[inline(always)]
pub fn CombineLengthCodes(
    mut inscode: uint16_t,
    mut copycode: uint16_t,
    mut use_last_distance: c_int,
) -> uint16_t {
    let ins = inscode as u32;
    let copy = copycode as u32;
    let bits64 = ((copy & 7) | ((ins & 7) << 3)) as uint16_t;

    if use_last_distance != 0 && ins < 8 && copy < 16 {
        return (bits64 as u32 | ((copy & 8) << 3)) as uint16_t;
    }

    let offset = 64u32
        + ((((copy >> 3) + 3 * (ins >> 3)) * 2) << 5)
        + ((0x520d40u32 >> ((((copy >> 3) + 3 * (ins >> 3)) * 2) as u32)) & 0xc0);
    (offset | bits64 as u32) as uint16_t
}
