#[inline(always)]
unsafe fn FindAllMatchesH10(
    mut self_0: *mut H10,
    mut dictionary: *const BrotliEncoderDictionary,
    mut data: *const uint8_t,
    ring_buffer_mask: size_t,
    cur_ix: size_t,
    max_length: size_t,
    max_backward: size_t,
    dictionary_distance: size_t,
    mut params: *const BrotliEncoderParams,
    mut matches: *mut BackwardMatch,
) -> size_t {
    let orig_matches: *mut BackwardMatch = matches;
    let cur_ix_masked: size_t = cur_ix & ring_buffer_mask;
    let mut best_len: size_t = 1;
    let short_match_max_backward: size_t =
        (if (*params).quality != HQ_ZOPFLIFICATION_QUALITY { 16 } else { 64 }) as size_t;
    let stop: size_t = if cur_ix < short_match_max_backward {
        0
    } else {
        cur_ix.wrapping_sub(short_match_max_backward)
    };

    // SAFETY: cur_ix_masked is masked into the ring buffer range; caller guarantees data points
    // to a valid ring buffer with enough readable bytes for the accesses performed by this routine.
    let cur_ptr = unsafe { data.add(cur_ix_masked) };
    // SAFETY: same preconditions as above for reading the first two bytes at cur_ptr.
    let cur0 = unsafe { *cur_ptr };
    // SAFETY: same preconditions as above; original code also reads cur_ix_masked + 1 directly.
    let cur1 = unsafe { *cur_ptr.add(1) };

    let mut i: size_t = cur_ix.wrapping_sub(1);
    while i > stop && best_len <= 2 {
        let backward: size_t = cur_ix.wrapping_sub(i);
        if backward > max_backward {
            break;
        }
        let prev_ix: size_t = i & ring_buffer_mask;
        // SAFETY: prev_ix is masked into the ring buffer range; caller guarantees readable bytes.
        let prev_ptr = unsafe { data.add(prev_ix) };
        // SAFETY: same preconditions as above.
        if unsafe { *prev_ptr == cur0 && *prev_ptr.add(1) == cur1 } {
            let len: size_t =
                FindMatchLengthWithLimit(prev_ptr as *const uint8_t, cur_ptr as *const uint8_t, max_length)
                    as size_t;
            if len > best_len {
                best_len = len;
                let out = matches;
                // SAFETY: matches points into writable output space provided by caller; advancing by 1
                // mirrors the original code and stays within that reserved space.
                matches = unsafe { matches.add(1) };
                InitBackwardMatch(out, backward, len);
            }
        }
        i = i.wrapping_sub(1);
    }

    if best_len < max_length {
        matches = StoreAndFindMatchesH10(
            self_0,
            data,
            cur_ix,
            ring_buffer_mask,
            max_length,
            max_backward,
            &raw mut best_len,
            matches,
        );
    }

    let mut dict_matches: [uint32_t; 38] = [kInvalidMatch; 38];
    let minlen: size_t = brotli_max_size_t(4, best_len.wrapping_add(1));
    if BrotliFindAllStaticDictionaryMatches(
        dictionary,
        cur_ptr as *const uint8_t,
        minlen,
        max_length,
        dict_matches.as_mut_ptr(),
    ) != 0
    {
        let maxlen: size_t = brotli_min_size_t(37, max_length);
        let max_distance = (*params).dist.max_distance;
        let mut l: size_t = minlen;
        while l <= maxlen {
            let dict_id: uint32_t = dict_matches[l as usize];
            if dict_id < kInvalidMatch {
                let distance: size_t =
                    dictionary_distance.wrapping_add((dict_id >> 5) as size_t).wrapping_add(1);
                if distance <= max_distance {
                    let out = matches;
                    // SAFETY: matches points into writable output space provided by caller; advancing by 1
                    // mirrors the original code and stays within that reserved space.
                    matches = unsafe { matches.add(1) };
                    InitDictionaryBackwardMatch(out, distance, l, (dict_id & 31) as size_t);
                }
            }
            l = l.wrapping_add(1);
        }
    }

    // SAFETY: matches and orig_matches are derived from the same output slice/base pointer.
    unsafe { matches.offset_from(orig_matches) as size_t }
}
