        cmd_code = ReadSymbol((*s).htree_command, br);
    } else {
        BrotliBitReaderSaveState(br, &raw mut memento);
        cmd_code = 0;
        if SafeReadSymbol((*s).htree_command, br, &raw mut cmd_code) == 0 {
            return BROTLI_FALSE;
