#[inline(always)]
extern "C" fn GetCopyLengthCode(mut copylen: size_t) -> uint16_t {
    if copylen < 10 as size_t {
        copylen.wrapping_sub(2 as size_t) as uint16_t
    } else if copylen < 134 as size_t {
        let v = copylen.wrapping_sub(6 as size_t);
        let nbits = Log2FloorNonZero(v).wrapping_sub(1 as uint32_t);
        (((nbits << 1) as size_t).wrapping_add(v >> nbits).wrapping_add(4 as size_t)) as uint16_t
    } else if copylen < 2118 as size_t {
        Log2FloorNonZero(copylen.wrapping_sub(70 as size_t)).wrapping_add(12 as uint32_t)
            as uint16_t
    } else {
        23 as uint16_t
    }
}
