```rust
unsafe fn FindBlocksLiteral(
    mut data: *const uint8_t,
    length: size_t,
    block_switch_bitcost: c_double,
    num_histograms: size_t,
    mut histograms: *const HistogramLiteral,
    mut insert_cost: *mut c_double,
    mut cost: *mut c_double,
    mut switch_signal: *mut uint8_t,
    mut block_id: *mut uint8_t,
) -> size_t {
    let alphabet_size: size_t = HistogramDataSizeLiteral() as size_t;
    let bitmap_len: size_t = num_histograms.wrapping_add(7 as size_t) >> 3 as c_int;
    let mut num_blocks: size_t = 1 as size_t;

    if num_histograms <= 1 as size_t {
        let mut i: size_t = 0;
        while i < length {
            // SAFETY: block_id points to an output buffer of at least `length` bytes per caller contract.
            unsafe { *block_id.add(i as usize) = 0 as uint8_t };
            i = i.wrapping_add(1);
        }
        return 1 as size_t;
    }

    memset(
        insert_cost as *mut c_void,
        0 as c_int,
        (::core::mem::size_of::<c_double>() as size_t)
            .wrapping_mul(alphabet_size)
            .wrapping_mul(num_histograms),
    );

    let mut i: size_t = 0;
    while i < num_histograms {
        // SAFETY: `histograms` has at least `num_histograms` elements and `insert_cost` has at least that many entries.
        unsafe {
            *insert_cost.add(i as usize) =
                FastLog2((*histograms.add(i as usize)).total_count_ as uint32_t as size_t);
        }
        i = i.wrapping_add(1);
    }

    i = alphabet_size;
    while i != 0 as size_t {
        i = i.wrapping_sub(1);
        let row = i.wrapping_mul(num_histograms);
        let mut j: size_t = 0;
        while j < num_histograms {
            // SAFETY: `histograms` and `insert_cost` are valid for the indexed accesses by construction above.
            unsafe {
                *insert_cost.add(row.wrapping_add(j) as usize) =
                    *insert_cost.add(j as usize)
                        - BitCost((*histograms.add(j as usize)).data_[i as usize] as size_t);
            }
            j = j.wrapping_add(1);
        }
    }

    memset(
        cost as *mut c_void,
        0 as c_int,
        (::core::mem::size_of::<c_double>() as size_t).wrapping_mul(num_histograms),
    );
    memset(
        switch_signal as *mut c_void,
        0 as c_int,
        (::core::mem::size_of::<uint8_t>() as size_t)
            .wrapping_mul(length)
            .wrapping_mul(bitmap_len),
    );

    static mut prologue_length: size_t = 2000 as size_t;
    static mut multiplier: c_double = 0.07f64 / 2000 as c_int as c_double;

    let mut byte_ix: size_t = 0;
    while byte_ix < length {
        // SAFETY: `data` points to `length` bytes, `cost` to `num_histograms` doubles,
        // `insert_cost` to `alphabet_size * num_histograms` doubles, and `block_id`/`switch_signal`
        // to their respective output buffers per caller contract.
        unsafe {
            let symbol: size_t = *data.add(byte_ix as usize) as size_t;
            let insert_row = insert_cost.add(symbol.wrapping_mul(num_histograms) as usize);
            let cost_ptr = cost;
            let mut min_cost: c_double = 1e99f64;
            let mut best_k: size_t = 0;
            let mut k: size_t = 0;

            while k < num_histograms {
                let new_cost = *cost_ptr.add(k as usize) + *insert_row.add(k as usize);
                *cost_ptr.add(k as usize) = new_cost;
                if new_cost < min_cost {
                    min_cost = new_cost;
                    best_k = k;
                }
                k = k.wrapping_add(1);
            }
            *block_id.add(byte_ix as usize) = best_k as uint8_t;

            let mut block_switch_cost: c_double = block_switch_bitcost;
            if byte_ix < prologue_length {
                block_switch_cost *= 0.77f64 + multiplier * byte_ix as c_double;
            }

            let signal_row = switch_signal.add(byte_ix.wrapping_mul(bitmap_len) as usize);
            k = 0 as size_t;
            while k < num_histograms {
                let mut v = *cost_ptr.add(k as usize) - min_cost;
                if v >= block_switch_cost {
                    let mask: uint8_t = ((1 as c_uint) << (k & 7 as size_t)) as uint8_t;
                    v = block_switch_cost;
                    let p = signal_row.add((k >> 3 as c_int) as usize);
                    *p = (*p as c_int | mask as c_int) as uint8_t;
                }
                *cost_ptr.add(k as usize) = v;
                k = k.wrapping_add(1);
            }
        }

        byte_ix = byte_ix.wrapping_add(1);
    }

    let mut byte_ix: size_t = length.wrapping_sub(1 as size_t);
    let mut ix_0: size_t = byte_ix.wrapping_mul(bitmap_len);
    // SAFETY: `block_id` has at least `length` bytes and `length > 0` in this path, matching original behavior.
    let mut cur_id: uint8_t = unsafe { *block_id.add(byte_ix as usize) };

    while byte_ix > 0 as size_t {
        let mask_0: uint8_t = ((1 as c_uint) << (cur_id as c_int & 7 as c_int)) as uint8_t;
        byte_ix = byte_ix.wrapping_sub(1);
        ix_0 = (ix_0 as c_ulong).wrapping_sub(bitmap_len as c_ulong) as size_t as size_t;
        // SAFETY: `switch_signal` and `block_id` are valid for the indexed accesses during this backward pass.
        unsafe {
            if *switch_signal.add(
                ix_0.wrapping_add((cur_id as c_int >> 3 as c_int) as size_t) as usize,
            ) as c_int
                & mask_0 as c_int
                != 0
            {
                let prev_id = *block_id.add(byte_ix as usize);
                if cur_id as c_int != prev_id as c_int {
                    cur_id = prev_id;
                    num_blocks = num_blocks.wrapping_add(1);
                }
            }
            *block_id.add(byte_ix as usize) = cur_id;
        }
    }

    num_blocks
}
